  'As soon as you have logged enough': 'Щойно набереться достатньо записів',
  'Day': 'День',
  'After how many workouts': 'Через скільки тренувань',
  'applied': 'застосовано',
  'declined': 'відхилено',
  'Your plan': 'Твій план',
  'What are you training for?': 'Заради чого ти тренуєшся?',
  'Where are you starting from?': 'З чого ти починаєш?',
  'How many days a week?': 'Скільки днів на тиждень?',
  'Which days suit you? (optional)': 'Які дні тобі зручні? (необов’язково)',
  'How long is a session?': 'Скільки триває заняття?',
  'min': 'хв',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Тренер підганяє обсяг під час, який у тебе справді є, включно з відпочинком між підходами.',
  'What can you train with?': 'З яким обладнанням ти тренуєшся?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Познач усе, до чого маєш доступ. Якщо лишити порожнім, Тренер використає всю бібліотеку.',
  'Anything to work around?': 'Щось потрібно обійти?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Травми, суглоби, що ниють, недоступні рухи або побутові обмеження, наприклад тренування о 6 ранку в квартирі.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'напр. «примхливе ліве плече, без жиму штанги над головою»',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Якщо щось справді болить, звернись до фахівця. Тренер планує обережно, але поставити діагноз не може.',
  'Anything else?': 'Щось іще?',
  'Exercises you love': 'Вправи, які тобі подобаються',
  'e.g. “deadlifts, anything with a kettlebell”': 'напр. «станова тяга, все з гирею»',
  'Exercises you would rather not': 'Вправи, яких ти волів би уникати',
  'e.g. “I hate lunges”': 'напр. «ненавиджу випади»',
  'Anything you want the Coach to know': 'Що ще варто знати Тренеру',
  'e.g. “I want visible arms progress by spring”': 'напр. «хочу помітний прогрес по руках до весни»',
  'Build my plan': 'Скласти мій план',
  'Your plan is live': 'Твій план активний',
  'That proposal can’t be read.': 'Цю пропозицію не вдається прочитати.',
  'Discard this plan?': 'Відхилити цей план?',
  'Nothing is saved, and you can ask again anytime.': 'Нічого не збережеться, і ти зможеш запитати знову будь-коли.',
  'Revision {0}': 'Версія {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'Замінить твій поточний тиждень. Дні, які план лишає порожніми, стануть днями відпочинку.',
  'Could not apply those changes': 'Не вдалося застосувати ці зміни',
  'Dismiss these suggestions?': 'Відхилити ці пропозиції?',
  'Nothing changes, and the Coach will remember you turned these down.': 'Нічого не зміниться, а Тренер запам’ятає, що ти їх відхилив.',
  'Dismiss': 'Відхилити',
  'Based on your last {0} sessions': 'За твоїми останніми {0} заняттями',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Твій план змінився відтоді, як Тренер його дивився. Пропозиції, що більше не підходять, показано сірим. Запроси новий розбір, щоб побачити їх знову.',
  'Doesn’t match your plan any more, so it can’t be applied.': 'Більше не відповідає твоєму плану, тож застосувати не можна.',
  'Apply nothing': 'Нічого не застосовувати',
  'Dismiss all': 'Відхилити все',
  'Reverted the last Coach changes.': 'Останні зміни Тренера скасовано.',
