  "{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "На цьому пристрої без входу записано тренувань: {0} і зважувань: {1}. Додай їх у профіль або лиши профіль точно таким, як на сервері.",
  "{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "На цьому пристрої без входу записано {0} тренування і {1} зважування. Додай їх у профіль або лиши профіль точно таким, як на сервері.",
  "{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "На цьому пристрої без входу записано {0} тренування і зважувань: {1}. Додай їх у профіль або лиши профіль точно таким, як на сервері.",
  "{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "На цьому пристрої без входу записано тренувань: {0} і {1} зважування. Додай їх у профіль або лиши профіль точно таким, як на сервері.",
  "Add them": "Додати",
  "Keep profile as is": "Лишити профіль як є",
  'Offline. Your changes are saved on this device and sync when you’re back online.': 'Офлайн. Зміни збережено на цьому пристрої, вони синхронізуються, щойно з’явиться мережа.',
