  'Editing a saved workout. Date and duration stay unchanged.': 'Ти редагуєш збережене тренування. Дата й тривалість не зміняться.',
  'A pull for every press, so the shoulders stay balanced.': 'На кожен жим своя тяга, щоб плечі залишалися збалансованими.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Дводенна ротація на три тренування на тиждень, складена під вказане тобою обладнання. Спершу базові вправи, на кожен жим своя тяга, і між днями достатньо перетинів, щоб ніщо не лишалося без навантаження два тижні.',
  'Based on the training already in this demo profile.': 'На основі тренувань, які вже є в цьому демо-профілі.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Вага тіла стоїть на місці вже чотири тижні, хоча мета набрати. Це питання кухні, а не тренувань. План тут ні до чого.',
  'Demo': 'Демо',
  'Demo data reset': 'Демо-дані скинуто',
  'Direct arm work, since you asked for it.': 'Пряма робота на руки, як ти й просив.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Усі основні підходи тут три тренування поспіль ішли на RPE 9,5 і вище, а вага не зрушила. Заміна руху на чотири тижні зазвичай виводить із застою швидше, ніж упертість у тому самому.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Приклади даних, що зберігаються лише в цьому браузері. Сміливо змінюй що завгодно.',
  'Full body A': 'Усе тіло A',
  'Full body B': 'Усе тіло B',
  'Horizontal pressing, the other half of the session.': 'Горизонтальний жим, друга половина тренування.',
  'Live demo. Everything stays in this browser.': 'Живе демо. Усе лишається в цьому браузері.',
  'No training history yet, so starting conservatively.': 'Історії тренувань ще немає, тож починаємо обережно.',
  'Passkey sign-in, sync across your devices, your own data.': 'Вхід за ключем доступу, синхронізація між твоїми пристроями, твої власні дані.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Повертає приклад плану, тренувань і зважувань до початкового стану.',
  'Reset': 'Скинути',
  'Reset demo data': 'Скинути демо-дані',
  'Reset demo data?': 'Скинути демо-дані?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Переглянуто на твоє прохання. Усе, до чого в тебе не було питань, лишилося як було.',
  'Same pattern, higher reps than day A.': 'Той самий рух, але більше повторень, ніж у день A.',
  'Self-host it in a minute →': 'Розгорни у себе за хвилину →',
  'Self-host openGym': 'Розгорнути openGym у себе',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Тренування затягуються приблизно на п’ятнадцять хвилин. Це та допоміжна вправа, яка найменше втратить від одного підходу менше.',
  'Start the demo': 'Запустити демо',
  'The main lower-body driver, where most of the strength comes from.': 'Головний рух для низу тіла, звідки береться більшість сили.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Ті самі рухи в інших варіаціях: перетинів вистачає для прогресу, відмінностей вистачає, щоб не набридло.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Спершу два великі рухи на низ тіла та жим, поки є сили.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Це демо працює повністю у твоєму браузері на прикладі даних. Нікуди нічого не надсилається. Вхід за ключем доступу й синхронізація між пристроями з’являються разом із сервером openGym, який ти розгортаєш у себе.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Три речі варто змінити, а про одну просто знати. Усе інше працює: і присід, і тяги прогресують за графіком.',
  'Vertical pressing.': 'Вертикальний жим.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Ти три тижні поспіль переносиш це тренування на суботу. Хай краще так і буде записано в плані, ніж ти щоразу його змінюватимеш.',
  'You’re in the demo': 'Ти в демо-режимі',
