  // --- v1.3.9: password sign-in next to passkeys, admin reset codes (#118) ---
  'Sign in with password': 'Увійти з паролем',
  'Password': 'Пароль',
  'Passkey': 'Ключ доступу',
  'Passkeys use {0}. A password works too, where passkeys do not.': 'Ключі доступу використовують {0}. Там, де вони не працюють, підійде й пароль.',
  'This browser doesn\'t support passkeys. Sign in with your name and password instead.': 'Цей браузер не підтримує ключі доступу. Увійди за іменем і паролем.',
  'Have a reset code from your admin?': 'Маєш код скидання від адміністратора?',
  'Reset your password': 'Скидання пароля',
  'Enter the code your admin gave you and choose a new password. It signs you out everywhere else.': 'Введи код від адміністратора й обери новий пароль. На всіх інших пристроях ти вийдеш з акаунта.',
  'Reset code': 'Код скидання',
  'New password': 'Новий пароль',
  'Repeat the password': 'Повтори пароль',
  'Current password': 'Поточний пароль',
  'At least {0} characters. A few unrelated words make a good one.': 'Щонайменше {0} символів. Кілька не пов’язаних між собою слів дають добрий пароль.',
  'Set password & sign in': 'Задати пароль і увійти',
  'Create profile': 'Створити профіль',
  'Pick a name and a password. You sign in with both.': 'Обери ім’я та пароль. Для входу знадобляться обидва.',
  'Enter your password.': 'Введи пароль.',
  'Enter the reset code.': 'Введи код скидання.',
  'The two passwords are not the same.': 'Паролі не збігаються.',
  'Set · sign in as “{0}”': 'Задано · вхід як «{0}»',
  'Not set. Handy for signing in where passkeys don’t work.': 'Не задано. Знадобиться для входу там, де ключі доступу не працюють.',
  'Set a password': 'Задати пароль',
  'Change password': 'Змінити пароль',
  'Sign in as “{0}” with it on devices where passkeys do not work. Saving signs you out everywhere else, and paired phones have to be paired again.': 'З ним ти входиш як «{0}» на пристроях, де ключі доступу не працюють. Після збереження ти вийдеш з акаунта всюди, крім цього пристрою, а спарені телефони доведеться спарувати знову.',
  'Confirm with passkey & save': 'Підтвердити ключем доступу й зберегти',
  'Forgot it? Confirm with your passkey instead': 'Не пам’ятаєш? Підтверди ключем доступу',
  'Password saved. You’re now signed out everywhere else.': 'Пароль збережено. На всіх інших пристроях ти тепер вийшов із системи.',
  'Remove password': 'Видалити пароль',
  'Remove your password?': 'Видалити пароль?',
  'Only your passkeys sign in to this profile afterwards.': 'Після цього увійти в профіль можна буде лише ключами доступу.',
  'Password removed': 'Пароль видалено',
  'Wrong name, e-mail or password.': 'Неправильне ім’я, e-mail або пароль.',
  'Use your profile name (or the e-mail you added to it) and your password.': 'Вкажи назву профілю (або e-mail, який ти до нього додав) і свій пароль.',
  'Name or e-mail': 'Ім’я або e-mail',
  'Enter your name or e-mail.': 'Введи ім’я або e-mail.',
  'E-mail (optional)': 'E-mail (необов’язково)',
  'Lets you sign in with it instead of your name. Nothing is ever sent to it.': 'Дає змогу входити з ним замість імені. На нього ніколи нічого не надсилається.',
  'That is not an e-mail address.': 'Це не адреса e-mail.',
  'Another profile already uses this e-mail address.': 'Інший профіль уже використовує цю адресу e-mail.',
  'Sign-in e-mail': 'E-mail для входу',
  'Sign in with “{0}” instead of your name': 'Входь з «{0}» замість імені',
  '“{0}” is saved, but signs in only once this profile has a password.': '«{0}» збережено, але для входу спрацює, лише коли в цього профілю буде пароль.',
  'Not set. Lets you sign in with an e-mail instead of your name.': 'Не задано. Дає змогу входити з e-mail замість імені.',
  'Change sign-in e-mail': 'Змінити e-mail для входу',
  'Add a sign-in e-mail': 'Додати e-mail для входу',
  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': 'Вводь його в «Увійти з паролем» замість назви профілю. Ми ніколи нічого на нього не надсилаємо; забутий пароль і далі скидає твій адмін.',
  'E-mail address': 'Адреса e-mail',
  'That is already your sign-in e-mail.': 'Це вже твій e-mail для входу.',
  'E-mail saved': 'E-mail збережено',
  'Remove e-mail': 'Видалити e-mail',
  'Remove your sign-in e-mail?': 'Видалити e-mail для входу?',
