  'E-mail removed': 'E-mail видалено',
  'Too many attempts. Try again {0}.': 'Забагато спроб. Спробуй ще раз {0}.',
  'Use at least {0} characters.': 'Використай щонайменше {0} символів.',
  'That password is too long.': 'Цей пароль задовгий.',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': 'Цей пароль надто легко вгадати. Спробуй довший або кілька випадкових слів поспіль.',
  'Another profile already signs in with this name.': 'Інший профіль уже входить під цим ім’ям.',
  'That invite code is not valid.': 'Цей код запрошення недійсний.',
  'Your current password is not right.': 'Поточний пароль неправильний.',
  'Your passkey could not be confirmed.': 'Не вдалося підтвердити ключ доступу.',
  'This password is the only way into your profile, so it cannot be removed.': 'Цей пароль є єдиним способом увійти у твій профіль, тому його не можна видалити.',
  'That reset code is wrong or has expired. Ask your admin for a new one.': 'Цей код скидання неправильний або прострочений. Попроси в адміністратора новий.',
