  // --- AI Coach: why a job failed or was refused (lib/coach-api.js JOB_ERRORS, BYOK_ERRORS) ---
  'The Coach isn’t set up on this instance.': 'Тренер не налаштований на цьому сервері.',
  'The Coach is taking a rest day. Try again tomorrow.': 'У Тренера день відпочинку. Спробуй ще раз завтра.',
  'The Coach took too long and gave up.': 'Тренер думав занадто довго й здався.',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'Тренеру не вдалося авторизуватися в постачальника. Власнику сервера потрібно перевірити налаштування.',
  'The Coach isn’t installed properly on this instance.': 'Тренер неправильно встановлений на цьому сервері.',
  'The Coach couldn’t run. The instance owner needs to check its setup.': 'Тренеру не вдалося запуститися. Власнику сервера потрібно перевірити налаштування.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'Тренер уперся в ліміт свого ШІ-провайдера. Спробуй пізніше, а якщо не допоможе, власнику сервера потрібно перевірити тариф або ключ.',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'ШІ-провайдер Тренера відхилив формат запиту. Власнику сервера потрібно спробувати іншу модель.',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'У ШІ-провайдера Тренера збій. Спробуй ще раз трохи згодом.',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'Тренер не зміг зв’язатися зі своїм ШІ-провайдером. Власнику сервера потрібно перевірити адресу та мережу.',
  'The Coach answered with something the app couldn’t use.': 'Тренер відповів чимось, що застосунок не зміг використати.',
  'The server restarted while the Coach was thinking.': 'Сервер перезапустився, поки Тренер думав.',
  'The Coach couldn’t read your training data.': 'Тренеру не вдалося прочитати дані твоїх тренувань.',
  'The Coach is switched off on this instance for safety reasons.': 'Тренер вимкнений на цьому сервері з міркувань безпеки.',
  'Something went wrong on the server.': 'Щось пішло не так на сервері.',
  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'Твій постачальник ШІ відхилив ключ на цьому телефоні. Перевір його в Налаштуваннях → ШІ-тренер.',
  'The Coach isn’t set up on this phone. Check Settings → AI Coach.': 'Тренер на цьому телефоні не налаштований. Перевір Налаштування → ШІ-тренер.',
  'Your AI provider couldn’t answer.': 'Твій постачальник ШІ не зміг відповісти.',
  'Something went wrong on this phone.': 'Щось пішло не так на цьому телефоні.',
