  '{0} set becomes {1}: one on each side, {2}s held every time.': '{0} підхід перетворюється на {1}: по одному на кожну сторону, щоразу утримання {2} с.',
  '{0} sets become {1}: one on each side, {2}s held every time.': { one: '{0} підхід перетворюється на {1}: по одному на кожну сторону, щоразу утримання {2} с.', few: '{0} підходи перетворюються на {1}: по одному на кожну сторону, щоразу утримання {2} с.', many: '{0} підходів перетворюються на {1}: по одному на кожну сторону, щоразу утримання {2} с.' },
  'For side planks, single-arm holds and the like. Trains each side on its own.': 'Для бічної планки, утримання однією рукою тощо. Кожна сторона тренується окремо.',
  'Compare photos': 'Порівняти фото',
