  '{0} exercises no longer exist and were left out.': { one: '{0} вправи більше немає, її пропущено.', few: 'Вправ, яких більше немає, пропущено: {0}.', many: 'Вправ, яких більше немає, пропущено: {0}.' },
  // --- show connection status, and the dot when it is off (#369, #330) ---
  'Show connection status': 'Показувати стан з’єднання',
  'Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.': 'Вимк.: смугу вгорі приховано. Крапка на «Головній» однаково попередить, якщо синхронізація застрягла.',
  'Connection problem': 'Проблема зі з’єднанням',
  // --- auto-backup into a folder chosen on Android (#161) ---
  'Backup folder': 'Папка резервних копій',
  'Chosen folder': 'Вибрана папка',
  'Use default folder': 'Використовувати типову папку',
  'This folder can’t be used for backups.': 'Цю папку не можна використовувати для резервних копій.',
  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym більше не може записувати в «{0}», тож копії знову зберігаються в Documents/openGym. Вибери папку ще раз, щоб повернутися до неї.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym більше не може записувати у вибрану папку, тож копії знову зберігаються в Documents/openGym. Вибери папку ще раз, щоб повернутися до неї.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Нагадувати, якщо я пропускаю заплановане тренування',
  'Nudge tone': 'Тон нагадування',
  'Friendly': 'Дружній',
  'Guilt trip': 'Тиснути на совість',
  'Drill sergeant': 'Сержант-інструктор',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Одне нагадування ввечері запланованого дня без записаного тренування, з 20:00 до 21:30. Після 3 пропущених днів поспіль воно замовкає до твого наступного тренування.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'Записали тренування на іншому пристрої? Перед нагадуванням телефон звіряється з вашим сервером, якщо дозволяє застосунку працювати у фоні. Під час відкриття застосунку все оновлюється в будь-якому разі.',
  'Everything okay?': 'Усе гаразд?',
  '{0} is still waiting. What’s up?': 'Тренування «{0}» досі чекає. Що сталося?',
  'No {0} today? Even a short session tomorrow counts.': 'Сьогодні без тренування «{0}»? Завтра зарахується навіть коротке.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Важкий день? Тренування «{0}» почекає. Завтра буде новий старт.',
  'Hey, {0} didn’t happen today. All good?': 'Гей, тренування «{0}» сьогодні не відбулося. Усе добре?',
  'I miss you': 'Я сумую за тобою',
  '{0} waited by the door all evening. For you.': 'Тренування «{0}» весь вечір чекало на тебе біля дверей. Саме на тебе.',
  'The barbell asked about you today. I didn’t know what to say.': 'Штанга сьогодні питала про тебе. Я не знав, що сказати.',
  'Was it something I said? {0} misses you.': 'Я щось не те сказав? Тренування «{0}» сумує за тобою.',
  'I saved you a spot on the bench. It’s still empty.': 'Я зайняв тобі місце на лаві. Воно досі порожнє.',
  'Attention, recruit!': 'Струнко, новобранцю!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Твої здобутки пакують валізи. Завтра «{0}», без відмовок!',
  '{0} doesn’t do itself, recruit. Move it!': 'Тренування «{0}» саме себе не зробить, новобранцю. Ворушися!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Відмовки не піднімають ваги. Завтра з’явитися на «{0}»!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Твої м’язи заявили про твоє зникнення. З’явитися на «{0}»!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Ця адреса відповідає, але це не сервер openGym. Перевір URL.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Ця адреса відповідає, але замість openGym відповіла сторінка входу або правило проксі. Пропусти /api/ до openGym без змін. Див. “Phone app and CORS” у docs/SELF_HOSTING.md.',
  'Switch sides': 'Зміни сторону',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Зберігає копію з датою в «{0}» після кожного тренування чи зміни програми й тримає {1} найновіших.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Зберігає копію з датою у вибрану теку після кожного тренування чи зміни програми й тримає {0} найновіших.',
