  'The loop stops. Your weekdays stay as they are, and the loop is saved for later.': 'Коло зупиняється. Твої дні тижня лишаються як є, а коло зберігається на потім.',
  'Routines in a loop. Whatever is next stays next until you train it, whatever the day.': 'Програми по колу. Наступна лишається наступною, доки ти її не зробиш, у будь-який день.',
