  'Skip completed exercises': 'Пропускати виконані вправи',
  // --- #551 device link from the phone ---
  'This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.': 'Цей застосунок не може підтвердити ключем доступу. Створіть код у браузері, де ви ввійшли в цей профіль, або спершу задайте там пароль.',
  // --- Settings → Apple Watch ---
  'Apple Watch': 'Apple Watch',
  'Weight': 'Вага',
  'Send workouts to the watch': 'Надсилати тренування на годинник',
  'Open on the watch': 'Відкривати на годиннику',
  'Start a workout on the phone and openGym pops up on your wrist.': 'Почни тренування на телефоні, і openGym зʼявиться на зап’ясті.',
  'Not allowed': 'Не дозволено',
  'Turn on Apple Health and the watch measures your heart rate for every set.': 'Увімкни Apple Здоров’я, і годинник міритиме пульс у кожному підході.',
  'Tap the wrist when a rest is over': 'Дотик до зап’ястя в кінці відпочинку',
  'No Apple Watch paired with this iPhone': 'До цього iPhone не під’єднано Apple Watch',
  'openGym is not on your Apple Watch yet. Install it in the Watch app.': 'openGym ще немає на твоєму Apple Watch. Установи його в програмі Watch.',
  'openGym is on your Apple Watch': 'openGym є на твоєму Apple Watch',
  'Last heard from the watch: {0}': 'Остання звістка від годинника: {0}',
  'The watch hasn’t checked in yet. Open openGym on it once.': 'Годинник ще не озивався. Відкрий на ньому openGym один раз.',
  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'На годиннику не дозволено. Дозволь у програмі «Здоров’я» на iPhone.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Пульс під час тренування і біля кожного підходу, тренування зберігається у «Здоров’ї». Годинник спитає один раз.',
  'Apple Health': 'Apple Здоров’я',
  'Write to Apple Health': 'Записувати в Apple Здоров’я',
  'Open Apple Health': 'Відкрити Apple Здоров’я',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Тренування і зважування потрапляють до Apple Здоров’я, щойно ти їх завершуєш або змінюєш.',
  'Writing to Apple Health': 'Запис до Apple Здоров’я',
  'Apple Health permission not granted': 'Дозвіл Apple Здоров’я не надано',
  'Could not write to Apple Health': 'Не вдалося записати до Apple Здоров’я',
  'Could not remove it from Apple Health': 'Не вдалося прибрати з Apple Здоров’я',
  'Stop writing to Apple Health?': 'Припинити запис до Apple Здоров’я?',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': 'Те, що openGym уже записав, може лишитися в Apple Здоров’я як твої дані або бути прибране.',
  'Your workouts in Apple Health': 'Твої тренування в Apple Здоров’я',
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': 'openGym може зберігати кожне тренування і зважування в Apple Здоров’я, а Apple Watch покаже пульс просто під час підходів.',
  'Workouts and weigh-ins saved to Apple Health': 'Тренування і зважування в Apple Здоров’я',
  'Heart rate per set on your Apple Watch': 'Пульс для кожного підходу на Apple Watch',
  'AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.': 'AirPods Pro 3 чи Powerbeats Pro 2 у вухах? iPhone виміряє пульс у кожному підході, якщо Apple Watch ще не взявся за це.',
  'Switch it off anytime in Settings': 'Вимкнеш будь-коли в Налаштуваннях',
  'You can change it anytime in Settings.': 'Це можна змінити будь-коли в Налаштуваннях.',
