  '“{0}” is done. Nicely lifted. What next?': '«{0}» пройдено. Чудово попрацював. Що далі?',
  'Week {0} of {1}: {2}% of your best 1RM': 'Тиждень {0} з {1}: {2}% твого найкращого 1RM',
  'Week {0} of {1}: deload week': 'Тиждень {0} з {1}: розвантажувальний тиждень',
