  "Disconnect this webhook?": "Від’єднати цей вебхук?",
  "Your server forgets the URL and its secret, and stops sending. Nothing changes on the other side.": "Сервер забуде URL і його секрет та перестане надсилати. На іншому боці нічого не зміниться.",
  "Webhook removed": "Вебхук видалено",
  "Sending": "Надсилання",
