  "Added": "Додано",
  "This lives in the openGym phone app.": "Це живе в застосунку openGym на телефоні.",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "Годинник чи ваги теж пишуть сюди? Garmin, COROS, Fitbit, Withings, Oura та інші потрапляють в openGym саме так.",
  "Now in Integrations": "Тепер в «Інтеграціях»",
  "Not on this phone": "Не на цьому телефоні",
  "This phone has no health store openGym can use.": "На цьому телефоні немає сховища здоров’я, яким може користуватися openGym.",
