  "Workouts and weigh-ins out, heart rate and scale readings in.": "Тренування й зважування туди, пульс і дані ваг сюди.",
  "Finished workouts and weigh-ins go to Apple Health.": "Завершені тренування й зважування йдуть в Apple Health.",
