  "Strong, FitNotes, Hevy CSV, GymMane or an Apple Health export.": "Strong, FitNotes, CSV із Hevy, GymMane або експорт Apple Health.",
  "Reads the export file of another app, once.": "Читає файл експорту іншого застосунку, один раз.",
  "Exercises are matched to the library, you check the rest.": "Вправи зіставляються з бібліотекою, решту перевіряєш ти.",
  "Spreadsheet (CSV)": "Таблиця (CSV)",
  "Every set, weigh-in and measurement, for Excel and friends.": "Кожен підхід, зважування й замір, для Excel та інших.",
  "One row per set, plus body weight and measurements.": "Один рядок на підхід, плюс вага тіла й заміри.",
  "openGym can read it back in later.": "openGym потім зможе прочитати його назад.",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "Повідомляй Home Assistant, n8n чи ntfy, коли закінчуєш тренування.",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "Підписане JSON-повідомлення, коли тренування закінчено, впав рекорд або ти зважився.",
  "Sent by your server, from whichever device you logged on.": "Надсилає твій сервер, з якого б пристрою ти не записав.",
  "Plans and reviews from the model you pick.": "Плани й розбори від обраної тобою моделі.",
  "Reads your plan and the last weeks of training when you ask.": "Читає твій план і останні тижні тренувань, коли попросиш.",
  "Set up on its own page.": "Налаштовується на своїй сторінці.",
  "MCP server": "Сервер MCP",
