  "When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.": "Відпочинок скінчився: 3, 2, 1, і утримання стартує. Пауза, заново чи стоп будь-коли.",
  "Holds start by themselves": "Стартує саме",
