  "NFC is off. Turn it on in your phone’s settings and try again.": "NFC вимкнено. Увімкни його в налаштуваннях телефона і спробуй ще раз.",
  "NFC sticker for this exercise": "NFC-мітка для цієї вправи",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "Наклей її на шафку, сумку чи двері залу. Один дотик телефоном, і ти на місці.",
