  "Tap it at the gym to start your workout or show your code.": "Торкнися її в залі, щоб почати тренування або показати код.",
  "That didn’t work. Hold your phone still on the sticker and try again.": "Не вийшло. Тримай телефон нерухомо на мітці і спробуй ще раз.",
