  "This sticker is for an exercise you don’t have.": "Ця мітка для вправи, якої в тебе немає.",
  "This sticker is locked. Try a blank one.": "Ця мітка заблокована. Спробуй порожню.",
  "This sticker is too small. NTAG213 or bigger works.": "Ця мітка замала. Підійде NTAG213 або більша.",
  "When you tap it": "Коли торкаєшся",
