  // --- Your year in openGym (lib/wrapped-cards.js, components/Wrapped.jsx) ---
  "Mostly in the morning. The early bird gets the barbell.": "Здебільшого вранці. Хто рано встає, тому штанга дає.",
  "Mostly around lunch. Who needs a lunch break anyway?": "Здебільшого в обід. Кому взагалі потрібна обідня перерва?",
  "Mostly in the afternoon. The sweet spot.": "Здебільшого вдень. Золота середина.",
  "Mostly in the evening. Work, then work out.": "Здебільшого ввечері. Спершу робота, потім тренування.",
  "Mostly late at night. The gym is all yours.": "Здебільшого пізно вночі. Увесь зал твій.",
  "Early bird": "Рання пташка",
  "Most of your sessions started before 9. The sun was still catching up.": "Більшість твоїх тренувань починалася до 9. Сонце ледве встигало.",
  "Night owl": "Нічна сова",
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": "Більшість твоїх тренувань починалася після 20:00. Тихий зал і є твій зал.",
  "Leg-day loyalist": "Вірність дню ніг",
