  "Record breaker": "Рекордсмен",
  "So many new bests, your trophy shelf needs a trophy shelf.": "Стільки нових рекордів, що твоїй полиці для кубків потрібна своя полиця для кубків.",
  "Weekend warrior": "Воїн вихідного дня",
  "Saturdays and Sundays are for lifting. Brunch can wait.": "Субота й неділя створені для заліза. Бранч зачекає.",
  "Cardio comet": "Кардіокомета",
  "Your heart is in great shape. Literally.": "Твоє серце в чудовій формі. Буквально.",
  "In it for the long haul": "Всерйоз і надовго",
