  "In and out": "Швидко й чітко",
  "Short, sharp sessions. Efficiency is your love language.": "Короткі, чіткі тренування. Твоя мова кохання: ефективність.",
  "Explorer": "Дослідник",
  "So many different exercises, boredom never stood a chance.": "Стільки різних вправ, що нудьга не мала жодного шансу.",
