  "Last-minute dash": "Забіг в останню хвилину",
  "Knees on the floor count just the same.": "Коліна на підлозі рахуються так само.",
  "Carry the shopping like it owes you money. Tall chest, slow steps.": "Неси покупки так, ніби вони винні тобі гроші. Груди вперед, повільні кроки.",
  "You found Rudolph! He says hi and hides again. New spot tomorrow.": "Рудольфа знайдено! Він вітається й знову ховається. Завтра нове місце.",
  "{0} bauble on the tree, {1} lit": "{0} іграшка на ялинці, {1} світиться",
