  "Profile picture": "Фото профілю",
  "Remove picture": "Прибрати фото",
  "That isn’t a photo. Try a JPEG, PNG, WebP or HEIC.": "Це не фото. Спробуй JPEG, PNG, WebP або HEIC.",
  "Use this photo": "Взяти це фото",
  "Zoom": "Масштаб",
  "Missed plan": "План пропущено",
  "Open this day": "Відкрити цей день",
  "Planned, not trained. Any other day this week still counts.": "Заплановано, але без тренування. Будь-який інший день цього тижня ще зарахується.",
  "Planned, not trained. Any workout that week would have counted.": "Заплановано, але без тренування. Зарахувалося б будь-яке тренування того тижня.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Заплановано, але без тренування. Не страшно: ти тренувався іншого дня, тож тиждень зараховано.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "1 заморозка в запасі, дається кожні 4 тижні з тренуваннями. Два пропущені тижні поспіль обривають серію.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "До 2 заморозок у запасі, по одній кожні 4 тижні з тренуваннями. Можна прикрити навіть два пропущені тижні поспіль.",
  "Change the freeze rule": "Змінити правило заморозок",
  "Every 4th week you train earns a freeze. You can bank 1.": "Кожен 4-й тиждень із тренуваннями дає заморозку. Можна мати 1.",
  "Every week counts. Miss one and the streak starts over.": "Кожен тиждень на рахунку. Пропустив один, і серія починається знову.",
  "From now on: {0}.": "Відтепер: {0}.",
  "From the week of {0} on: {1}.": "З тижня {0}: {1}.",
  "Generous": "Щедре",
  "Gentle": "М'яке",
  "How forgiving should your week streak be?": "Наскільки поблажливою буде твоя тижнева серія?",
  "How strict should your streak be?": "Наскільки суворою буде твоя серія?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Пропустив тиждень? Заморозка його прикриє: серія триває, просто цей тиждень нічого не додає. Два пропущені тижні поспіль, і серія почнеться знову.",
  "No freezes": "Без заморозок",
  "No freezes on your rule. Every week counts.": "У твоєму правилі немає заморозок. Кожен тиждень на рахунку.",
  "No freezes on your rule: a week without a workout starts it over.": "У твоєму правилі немає заморозок: тиждень без тренування, і серія починається знову.",
  "No workout, and your rule has no freezes, so the streak started over.": "Тренування не було, а заморозок у твоєму правилі немає, тож серія почалася знову.",
  "Weeks already counted stay as they are.": "Уже пораховані тижні лишаться як є.",
  "You can change it later in Settings. A change counts from then on.": "Це можна змінити пізніше в налаштуваннях. Зміна діє з цього моменту.",
  "Your rule right now: {0}.": "Твоє правило зараз: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "Серія рахує тижні бодай з одним тренуванням. Заморозки можуть прикрити випадково пропущений тиждень.",
  "{0} since the week of {1}.": "{0} з тижня {1}.",
  "This phone has no print service. Turn one on in its settings and try again.": "На цьому телефоні немає служби друку. Увімкни її в налаштуваннях і спробуй ще раз.",
