  "{0} sees only what is on here.": "{0} бачить лише те, що тут увімкнено.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Ти дозволяєш цьому тренеру бачити позначені тут категорії та змінювати ті, що позначені як «Пропонує» або «Змінювати напряму». Якщо тренер працює в залі, керівник цього залу бачить категорії в рядку керівника залу, і ніколи більше, ніж перегляд. Ти можеш змінити це або відключитися будь-коли, і все припиняє діяти, щойно ти це зробиш. Кожен перегляд і кожна зміна записуються в твій журнал доступу, який можеш читати лише ти.",
