  "Shared by people on {0}. Take a copy, it is yours.": "Цим поділилися люди на {0}. Візьми копію, вона твоя.",
  "Shared. Your gym thanks you.": "Опубліковано. Твій зал каже дякую.",
  "Sharing is paused for your account on this server. Questions? Ask the admin.": "Публікацію призупинено для твого акаунта на цьому сервері. Питання? Запитай адміна.",
  "Sharing works once you are connected to a server.": "Ділитися можна, коли ти під'єднаний до сервера.",
