  "Tell us what is up. Only the admins see it, not {0}.": "Розкажи, у чому справа. Бачать лише адміни, не {0}.",
  "Thanks. An admin will take a look.": "Дякуємо. Адмін подивиться.",
  "That did not work. Try again in a moment.": "Не вийшло. Спробуй ще раз трохи згодом.",
  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "Цим файлом тут ділитися не можна ніколи. Зображення й анімації з вбудованої бібліотеки ліцензовані.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "У файлі досі є приховані дані, наприклад місцезнаходження. Додай його в застосунку заново й поділися новою копією.",
  "That is not shared any more.": "Це більше не опубліковано.",
  "That one is not in the community any more.": "Цього більше немає у спільноті.",
  "That one is yours.": "Це твоє.",
  "That sound did not come through.": "Звук не дійшов.",
  "That tip did not come through.": "Порада не дійшла.",
  "The sharing text changed. Have a quick read and try again.": "Текст про публікацію змінився. Швидко прочитай і спробуй знову.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Це видно всім на цьому сервері: будь-хто з акаунтом тут може це переглянути, спробувати й скопіювати. Твоє ім'я та дата завжди йдуть разом із цим. Ділися лише своїм: тим, що ти зробив, записав або маєш право передати далі. Зображення й анімації вправ із вбудованої бібліотеки ліцензовані, і ділитися ними не можна ніколи. Припинити ділитися можна будь-коли; копії, які інші вже взяли, залишаться в них.",
  "This kind of item cannot be taken.": "Такий елемент узяти не можна.",
  "This server has no community library.": "На цьому сервері немає бібліотеки спільноти.",
  "Tick that it is yours to share first.": "Спершу познач, що це твоє і ти можеш цим ділитися.",
  "Tips": "Поради",
  "Tips from your gym": "Поради з твого залу",
