  "You have that one already.": "Це в тебе вже є.",
  "You have {0} sounds already. Remove one first.": "У тебе вже {0} звуків. Спершу видали один.",
  "You reported this one already. Thanks.": "Ти вже поскаржився на це. Дякуємо.",
