  "After a year": "Через рік",
  "After {0} days": "Через {0} дн.",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "Скопіюй його зараз: openGym показує його лише один раз. Поводься з ним як із паролем.",
