  "Last photo: {0} day ago. Same spot, same light?": "Останнє фото: {0} день тому. Те саме місце, те саме світло?",
  "Last photo: {0} days ago. Same spot, same light?": { one: "Останнє фото: {0} день тому. Те саме місце, те саме світло?", few: "Останнє фото: {0} дні тому. Те саме місце, те саме світло?", many: "Останнє фото: {0} днів тому. Те саме місце, те саме світло?", other: "Останнє фото: {0} днів тому. Те саме місце, те саме світло?" },
  "A buzz for each phase": "Вібрація на кожну фазу",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Копія всього раз на день у твоїй власній папці: Nextcloud, ownCloud, NAS, будь-що, що говорить WebDAV. Твій сервер, і більше нічий.",
  "A sound for each kind of rest": "Свій звук для кожного виду відпочинку",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "Позначка на кожному дні з тренуванням, і скільки було підходів. Бачиш тільки ти, як і план.",
  "A tone for each phase": "Свій сигнал для кожної фази",
  "Again": "Ще раз",
  "An app password is best": "Найкраще пароль застосунку",
  "Back up every day": "Копія щодня",
  "Back up now": "Зберегти копію зараз",
  "Back up to WebDAV": "Копія у WebDAV",
