  "1RM table, RPE load, DOTS, BMI, body fat, pace.": "Таблиця 1ПМ, вага за RPE, DOTS, ІМТ, жир, темп.",
  "A trophy and a buzz the moment a set beats a record, and the same mark in History.": "Кубок і вібрація, щойно підхід б'є рекорд, і та сама позначка в історії.",
  "About": "Приблизно",
  "Add your height once and every body number below fills in. It stays on this profile.": "Вкажи зріст один раз, і всі показники тіла нижче заповняться. Він залишиться в цьому профілі.",
  "Beats your best e1RM": "Б'є твій найкращий e1RM",
