  "Body weight ({0})": "Вага тіла ({0})",
  "Calculators, already filled in from your log.": "Калькулятори, вже заповнені з твого журналу.",
  "Cheer on a record": "Відзначити рекорд",
  "Estimates, not a lab. Good for planning, not for arguing.": "Оцінки, а не лабораторія. Для планів, а не для суперечок.",
