  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "У цій версії openGym немає зв’язку з Garmin: частина Garmin не відкрита. У версіях з App Store, Google Play і GitHub він є.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "На цьому телефоні немає Garmin Connect. Встанови його, під’єднай там годинник і повертайся сюди.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect треба оновити, перш ніж openGym зможе говорити з годинником.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Не вдалося зв’язатися з Garmin Connect. Спробуй трохи згодом.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Обери свій Garmin у Garmin Connect, і тренування з’являться на зап’ясті.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect ще не знає жодного годинника. Спершу під’єднай свій там.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym є на твоєму Garmin. Підходи, записані на зап’ясті, приходять сюди.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym є на твоєму Garmin. Усе наздожене, щойно годинник буде поруч.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Твій Garmin тут, але openGym на ньому ще немає. Встанови його й відкрий один раз на годиннику.",
  "Not in reach": "Поза досяжністю",
  "openGym isn’t on it yet": "openGym на ньому ще немає",
  "Your Garmins": "Твої Garmin",
  "Choose watches": "Вибрати годинники",
  "Look again": "Пошукати знову",
  "Get openGym for Garmin": "openGym для Garmin",
  "Start a workout on the phone and your Garmin asks to open openGym.": "Почни тренування на телефоні, і Garmin запропонує відкрити openGym.",
