  "Estimated strength": "Оцінка сили",
  "Every single week. That is a habit, not a phase.": "Кожного тижня без винятку. Це вже звичка, а не етап.",
  "Every week you showed up counted.": "Кожен тиждень, коли ти прийшов, зараховано.",
  "Everything aches": "Болить усе",
  "Exercise of the month": "Вправа місяця",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Для картки «Форма дня» у Статистиці та твоєї відмітки. Читається лише на цьому телефоні й нікуди не надсилається.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Чотири дотики про сон, енергію, крепатуру та стрес. У важкий день openGym запропонує полегшити тренування, а за кілька тижнів ти побачиш, що спільного у твоїх добрих днів.",
  "Frazzled": "На нервах",
  "From Apple Health, read-only, on this phone only.": "З Apple Health, лише читання, лише на цьому телефоні.",
  "From Health Connect, read-only, on this phone only.": "З Health Connect, лише читання, лише на цьому телефоні.",
  "Full of beans": "Сповнений сил",
  "HRV (RMSSD)": "ВСР (RMSSD)",
  "HRV (SDNN)": "ВСР (SDNN)",
  "How are you today?": "Як ти сьогодні?",
  "How your days and your workouts line up": "Як пов’язані твої дні й тренування",
  "Insights show up once there is enough to compare: {0} of {1} workouts so far.": "Висновки з’являться, коли буде що порівнювати: поки {0} з {1} тренувань.",
  "Just today. This session sits out of progression, so your next targets stay put.": "Лише сьогодні. Це тренування не враховується в прогресії, тож наступні цілі залишаються на місці.",
  "Leaning that way": "Схиляється до цього",
  "Lighter day: 10% off the weights. Progression sits this one out.": "Легкий день: вага на 10% менша. Прогресія цього разу пропускає.",
  "Lighter day: one set fewer per exercise. Progression sits this one out.": "Легкий день: на один підхід менше в кожній вправі. Прогресія цього разу пропускає.",
  "More than last month. Momentum looks good on you.": "Більше, ніж минулого місяця. Розгін тобі пасує.",
  "New moves, new muscles asking questions. Curiosity pays.": "Нові рухи, нові м’язи ставлять питання. Цікавість окупається.",
