  "Patterns, not proof. Sleep is rarely the only thing that changed that day.": "Закономірності, а не докази. Сон рідко єдине, що змінилося того дня.",
  "Play your month": "Переглянути свій місяць",
  "Pretty consistent so far": "Поки досить стабільно",
