  "Resting heart rate": "Пульс у спокої",
  "Rough one. Take it easier today?": "Важкий день. Сьогодні легше?",
  "Running on fumes": "На останньому подиху",
  "Same as {0}. Steady wins.": "Як у місяці «{0}». Сталість перемагає.",
  "Share my month": "Поділитися моїм місяцем",
  "Showing up is the whole trick, and you did it.": "Увесь секрет у тому, щоб прийти, і ти це зробив.",
