  "Sleep": "Сон",
  "Sleep, energy, soreness and stress in four taps before you train. On a rough day it offers to go lighter.": "Сон, енергія, крепатура та стрес у чотири дотики перед тренуванням. У важкий день пропонує полегшити.",
