  "Your month in openGym": "Твій місяць в openGym",
  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym попросить у Apple Health твій сон, пульс у спокої, варіабельність серцевого ритму та кроки. Дозволь те, що хочеш. Дані залишаються на цьому телефоні, у власному файлі openGym, і ніколи не йдуть на сервер.",
  "openGym asks Health Connect for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym попросить у Health Connect твій сон, пульс у спокої, варіабельність серцевого ритму та кроки. Дозволь те, що хочеш. Дані залишаються на цьому телефоні, у власному файлі openGym, і ніколи не йдуть на сервер.",
